// 考生选中的志愿
let selectedVolunteers = [];

// 选中的选考科目
let selectedSubjects = [];

// ==================== 页面导航 ====================

function showPage(pageId) {
  // Hide all pages
  document.querySelectorAll('.page-section').forEach(p => p.classList.remove('active'));
  // Show target page
  document.getElementById('page-' + pageId).classList.add('active');
  // Update nav buttons
  document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
  event.target.classList.add('active');
}

// ==================== 选考科目选择 ====================

document.querySelectorAll('.subject-tag').forEach(tag => {
  tag.addEventListener('click', () => {
    const subject = tag.dataset.subject;
    if (tag.classList.contains('selected')) {
      tag.classList.remove('selected');
      selectedSubjects = selectedSubjects.filter(s => s !== subject);
    } else {
      // 物理/历史必选一个，其他最多选两个
      if (subject === '物理' || subject === '历史') {
        document.querySelectorAll('.subject-tag').forEach(t => {
          if (t.dataset.subject === '物理' || t.dataset.subject === '历史') {
            t.classList.remove('selected');
          }
        });
        selectedSubjects = selectedSubjects.filter(s => s !== '物理' && s !== '历史');
      } else {
        // 检查是否已选两个非必选科目
        const otherSelected = selectedSubjects.filter(s => s !== '物理' && s !== '历史');
        if (otherSelected.length >= 2) {
          alert('选考科目最多选择2个（非物理/历史科目）');
          return;
        }
      }
      tag.classList.add('selected');
      selectedSubjects.push(subject);
    }
  });
});

// ==================== 清空表单 ====================

function clearForm() {
  document.getElementById('scoreForm').reset();
  document.querySelectorAll('.subject-tag').forEach(t => t.classList.remove('selected'));
  selectedSubjects = [];
  document.getElementById('resultsSection').style.display = 'none';
}

// ==================== 智能推荐算法 ====================

function generateRecommendation() {
  const totalScore = parseInt(document.getElementById('totalScore').value);
  const chinese = parseInt(document.getElementById('chineseScore').value);
  const math = parseInt(document.getElementById('mathScore').value);
  const english = parseInt(document.getElementById('englishScore').value);

  if (!totalScore || totalScore < 300 || totalScore > 750) {
    alert('请输入有效的高考总分（300-750）');
    return;
  }

  // 显示结果区域
  document.getElementById('resultsSection').style.display = 'block';
  
  // 显示分数
  document.getElementById('displayScore').textContent = totalScore;
  document.getElementById('displayChinese').textContent = chinese || '--';
  document.getElementById('displayMath').textContent = math || '--';
  document.getElementById('displayEnglish').textContent = english || '--';

  // 获取最新年份数据作为推荐基准（优先2025，其次2024）
  const dataYear = historicalData[2025] ? 2025 : (historicalData[2024] ? 2024 : 2023);
  const latestData = historicalData[dataYear];
  console.log('使用' + dataYear + '年数据进行推荐，共' + (latestData?.length || 0) + '条记录');
  
  // 计算推荐
  const recommendations = calculateRecommendations(totalScore, selectedSubjects, latestData, dataYear);
  
  // 渲染结果
  renderRecommendations(recommendations);
}

// 根据分数查找对应位次（累计人数）
function getRank(score, year) {
  const segments = scoreSegments[String(year)];
  if (!segments) return null;
  const scores = Object.keys(segments).map(Number).sort((a, b) => b - a);
  for (const s of scores) {
    if (s <= score) return segments[s];
  }
  return scores.length > 0 ? segments[scores[scores.length - 1]] : null;
}

function calculateRecommendations(score, subjects, data, year) {
  const studentRank = getRank(score, year);
  const chong = [];  // 冲
  const wen = [];    // 稳
  const bao = [];    // 保

  data.forEach(school => {
    // 检查选科要求是否满足
    if (school.subjects.length > 0) {
      const hasRequired = school.subjects.every(s => subjects.includes(s));
      if (!hasRequired) return;
    }

    // 用位次判断（更精准）
    const schoolRank = getRank(school.minScore, year);

    if (studentRank !== null && schoolRank !== null) {
      const rankDiff = studentRank - schoolRank;  // 负数=排名更靠前

      // 冲：位次在院校录取位次~+5%区间（录取位次的105%以内）
      const chongThreshold = schoolRank * 1.08;
      // 稳：位次在院校录取位次的95%~105%区间
      const wenLow = schoolRank * 0.93;
      const wenHigh = schoolRank * 1.08;
      // 保：位次明显优于院校录取位次（低于95%）
      const baoThreshold = schoolRank * 0.93;

      if (rankDiff > 0 && rankDiff <= chongThreshold - schoolRank) {
        chong.push({ ...school, rankDiff, studentRank, schoolRank });
      } else if (rankDiff <= 0 && rankDiff >= wenLow - schoolRank) {
        wen.push({ ...school, rankDiff, studentRank, schoolRank });
      } else if (rankDiff < 0 && rankDiff < wenLow - schoolRank) {
        bao.push({ ...school, rankDiff, studentRank, schoolRank });
      }
    } else {
      // 降级：用分数差
      const scoreDiff = score - school.minScore;
      if (scoreDiff >= -15 && scoreDiff < 0) {
        chong.push({ ...school, scoreDiff });
      } else if (scoreDiff >= 0 && scoreDiff <= 10) {
        wen.push({ ...school, scoreDiff });
      } else if (scoreDiff > 10) {
        bao.push({ ...school, scoreDiff });
      }
    }
  });

  // 按位次差排序（冲：差值小的在前，稳/保：差值大的在前）
  chong.sort((a, b) => (b.rankDiff ?? b.scoreDiff) - (a.rankDiff ?? a.scoreDiff));
  wen.sort((a, b) => (a.rankDiff ?? a.scoreDiff) - (b.rankDiff ?? b.scoreDiff));
  bao.sort((a, b) => (a.rankDiff ?? a.scoreDiff) - (b.rankDiff ?? b.scoreDiff));

  return {
    chong: chong.slice(0, 8),
    wen: wen.slice(0, 10),
    bao: bao.slice(0, 7)
  };
}

function renderRecommendations(rec) {
  const container = document.getElementById('recommendationResults');
  let html = '';

  // 冲
  if (rec.chong.length > 0) {
    rec.chong.forEach(school => {
      html += createResultCard(school, 'chong');
    });
  }

  // 稳
  if (rec.wen.length > 0) {
    rec.wen.forEach(school => {
      html += createResultCard(school, 'wen');
    });
  }

  // 保
  if (rec.bao.length > 0) {
    rec.bao.forEach(school => {
      html += createResultCard(school, 'bao');
    });
  }

  if (html === '') {
    html = '<div class="empty-state" style="grid-column: 1/-1;"><p>暂无符合条件的推荐院校，请调整选考科目或分数后重试</p></div>';
  }

  container.innerHTML = html;
}

function createResultCard(school, type) {
  const labels = {
    chong: { tag: '冲一冲', desc: '录取有风险，选择需谨慎' },
    wen: { tag: '稳一稳', desc: '录取把握较大' },
    bao: { tag: '保一保', desc: '录取非常稳妥' }
  };

  const label = labels[type];
  const levelColors = {
    '985/211': '#E8A87C',
    '一本': '#7AAE8E',
    '二本': '#9BB5D3'
  };

  // 显示位次信息（如果有）
  const hasRank = school.studentRank != null && school.schoolRank != null;
  const diffDisplay = hasRank
    ? `<div class="result-score-item">
        <span class="result-score-label">我的位次</span>
        <span class="result-score-value">${school.studentRank}</span>
      </div>
      <div class="result-score-item">
        <span class="result-score-label">院校位次</span>
        <span class="result-score-value">${school.schoolRank}</span>
      </div>`
    : `<div class="result-score-item">
        <span class="result-score-label">我的分差</span>
        <span class="result-score-value" style="color: ${(school.scoreDiff || 0) >= 0 ? '#4A9B6E' : '#E8A87C'}">
          ${(school.scoreDiff || 0) >= 0 ? '+' : ''}${(school.scoreDiff || 0)}
        </span>
      </div>`;

  return `
    <div class="result-card ${type} fade-in">
      <span class="result-tag ${type}">${label.tag}</span>
      <div class="result-school">${school.school}</div>
      <div class="result-major">${school.selection_req || '不限'} · ${school.level}</div>
      <div class="result-score">
        <div class="result-score-item">
          <span class="result-score-label">最低分</span>
          <span class="result-score-value">${school.minScore}</span>
        </div>
        ${diffDisplay}
      </div>
      <div style="margin-top: 12px; display: flex; gap: 8px;">
        <button class="btn-secondary" style="padding: 8px 16px; font-size: 13px;" onclick="addToVolunteer('${school.school}', ${school.minScore})">加入志愿表</button>
        <button class="btn-secondary" style="padding: 8px 16px; font-size: 13px;" onclick="showSchoolDetail('${school.code}')">查看详情</button>
      </div>
    </div>
  `;
}

// ==================== 志愿表管理 ====================

function addToVolunteer(schoolName, minScore) {
  if (selectedVolunteers.length >= 30) {
    alert('本科批最多填报30个院校专业组');
    return;
  }

  const userScore = parseInt(document.getElementById('totalScore').value) || 0;
  
  selectedVolunteers.push({
    num: selectedVolunteers.length + 1,
    school: schoolName,
    minScore: minScore,
    scoreDiff: userScore - minScore
  });

  renderVolunteerTable();
  alert(`已添加：${schoolName}`);
}

function renderVolunteerTable() {
  const container = document.getElementById('volunteerList');
  
  if (selectedVolunteers.length === 0) {
    container.innerHTML = `
      <div class="empty-state" style="padding: 40px;">
        <div class="empty-state-icon">📝</div>
        <p>从"数据查询"或"推荐结果"中添加院校到志愿表</p>
      </div>
    `;
    return;
  }

  let html = '';
  selectedVolunteers.forEach((v, index) => {
    html += `
      <div class="volunteer-row">
        <span class="volunteer-num">${v.num}</span>
        <span class="volunteer-name">${v.school}</span>
        <span class="volunteer-score">${v.minScore}</span>
        <span class="volunteer-score" style="color: ${v.scoreDiff >= 0 ? '#4A9B6E' : '#E8A87C'}">
          ${v.scoreDiff >= 0 ? '+' : ''}${v.scoreDiff}
        </span>
        <button onclick="removeVolunteer(${index})" style="padding: 4px 12px; border: none; background: #FFF4ED; color: #D4846A; border-radius: 4px; cursor: pointer; font-size: 12px;">删除</button>
      </div>
    `;
  });
  container.innerHTML = html;
}

function removeVolunteer(index) {
  selectedVolunteers.splice(index, 1);
  // 重新编号
  selectedVolunteers.forEach((v, i) => v.num = i + 1);
  renderVolunteerTable();
}

function exportVolunteer() {
  if (selectedVolunteers.length === 0) {
    alert('请先添加志愿');
    return;
  }

  let content = '北京2026高考志愿表\n';
  content += '========================\n\n';
  selectedVolunteers.forEach(v => {
    content += `${v.num}. ${v.school}（2024最低分：${v.minScore}，分差：${v.scoreDiff >= 0 ? '+' : ''}${v.scoreDiff}）\n`;
  });
  content += '\n========================\n';
  content += '本表仅供参考，请以官方填报系统为准\n';

  const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = '北京2026高考志愿表.txt';
  a.click();
  URL.revokeObjectURL(url);
}

function saveVolunteer() {
  localStorage.setItem('gaokao_volunteers', JSON.stringify(selectedVolunteers));
  alert('志愿表已保存');
}

// 页面加载时恢复已保存的志愿
window.addEventListener('DOMContentLoaded', () => {
  const saved = localStorage.getItem('gaokao_volunteers');
  if (saved) {
    selectedVolunteers = JSON.parse(saved);
    renderVolunteerTable();
  }
});

// ==================== 数据查询筛选 ====================

function filterData() {
  const year = document.getElementById('filterYear').value;
  const batch = document.getElementById('filterBatch').value;
  const level = document.getElementById('filterLevel').value;
  const schoolName = document.getElementById('filterSchool').value.toLowerCase();

  if (!year) {
    alert('请选择年份');
    return;
  }

  const data = historicalData[year] || [];
  
  let filtered = data.filter(s => {
    if (batch && s.batch !== batch) return false;
    if (level && s.level !== level) return false;
    if (schoolName && !s.school.toLowerCase().includes(schoolName)) return false;
    return true;
  });

  renderDataTable(filtered);
}

function renderDataTable(data) {
  const container = document.getElementById('dataTableContainer');
  
  if (data.length === 0) {
    container.innerHTML = `
      <div class="empty-state">
        <div class="empty-state-icon">🔍</div>
        <p>未找到符合条件的院校</p>
      </div>
    `;
    return;
  }

  let html = `
    <table class="data-table">
      <thead>
        <tr>
          <th>学校</th>
          <th>选科要求</th>
          <th>批次</th>
          <th>层次</th>
          <th>2024最低分</th>
          <th>备注(选科/位次)</th>
          <th>操作</th>
        </tr>
      </thead>
      <tbody>
  `;

  data.forEach(s => {
    html += `
      <tr>
        <td><strong>${s.school}</strong></td>
        <td>${s.selection_req || '不限'}</td>
        <td>${s.batch}</td>
        <td>${s.level}</td>
        <td>${s.minScore}</td>
        <td>${s.remark || '-'}</td>
        <td>
          <button onclick="addToVolunteer('${s.school}', ${s.minScore})" class="btn-secondary" style="padding: 6px 12px; font-size: 12px;">加入志愿表</button>
        </td>
      </tr>
    `;
  });

  html += '</tbody></table>';
  container.innerHTML = html;
}

function showSchoolDetail(code) {
  window.open('https://gaokao.chsi.com.cn/zsgs/zybk/zyzl.jsp?daima=' + code, '_blank');
}

